examples.code:
for a in (True, False):
    for b in (True, False):
        print(a, b, a and b, a or b)

username = 'Mary'
password = 'swordfish'
if username == 'Mary':
    print('Hello, Mary')
    if password == 'swordfish':
        print('Access granted.')
    else:
        print('Wrong password.')

name, age = 'Carol', 3000
if name == 'Alice':
    print('Hi, Alice.')
elif age < 12:
    print('You are not Alice, kiddo.')
elif age > 2000:
    print('Alice is not an undead vampire.')
elif age > 100:
    print('You are not Alice, grannie.')

for age in (5, 50, 150, 3000):
    if age < 12:
        print(age, 'kiddo')
    elif age > 100:
        print(age, 'grannie')
    elif age > 2000:
        print(age, 'vampire')
    else:
        print(age, 'stranger')

opposite_day = True
if opposite_day == True:
    say_it = True
else:
    say_it = False
if opposite_day == True:
    say_it = not say_it
if say_it == True:
    print('Today is Opposite Day.')
else:
    print('Today is not Opposite Day.')

advertised = 10
unit = 'TB'
if unit == 'TB' or unit == 'tb':
    discrepancy = 10**12 / 2**40
elif unit == 'GB' or unit == 'gb':
    discrepancy = 10**9 / 2**30
else:
    discrepancy = 1
real = advertised * discrepancy
print('Real capacity:', round(real, 2), unit)

for n in (7, 10):
    print(n, 'even' if n % 2 == 0 else 'odd')
print('adult' if 20 >= 18 else 1 / 0)

names = ['Al', 'Alice', 'Bartholomew']
for name in names:
    if (size := len(name)) > 3:
        print(name, 'has', size, 'letters')

